style.css:
@-moz-document domain("sammo.uk") {
/* =========================================
     1. THEME VARIABLES
     ========================================= */

  :root {
    color-scheme: light dark;

    --rainbow: linear-gradient(
      110deg,
      #ff4d6d 0%,
      #ff922b 18%,
      #ffd43b 35%,
      #51cf66 52%,
      #339af0 70%,
      #845ef7 85%,
      #f06595 100%
    );

    --rainbow-soft: linear-gradient(
      135deg,
      rgba(255, 77, 109, 0.12),
      rgba(255, 146, 43, 0.12),
      rgba(255, 212, 59, 0.12),
      rgba(81, 207, 102, 0.12),
      rgba(51, 154, 240, 0.12),
      rgba(132, 94, 247, 0.12)
    );

    --rainbow-shadow:
      0 4px 18px rgba(132, 94, 247, 0.14);

    --rainbow-radius: 16px;
    --rainbow-focus: #a855f7;

    --rainbow-purple: #bf5af2;
    --rainbow-blue: #339af0;
    --rainbow-pink: #f06595;

    --rainbow-card-bg: #1c1a1a;
    --rainbow-page-bg: #100e0e;
  }

  /* =========================================
     2. GLOBAL ACCENTS
     ========================================= */

  ::selection {
    color: #ffffff;
    background: #845ef7;
  }

  :focus-visible {
    outline: 2px solid var(--rainbow-focus) !important;
    outline-offset: 3px;
  }

  /* =========================================
     3. HEADINGS
     ========================================= */

  h1 {
    background: var(--rainbow);
    background-clip: text;
    -webkit-background-clip: text;
    color: transparent !important;
    -webkit-text-fill-color: transparent;
  }

  h2 {
    text-decoration-line: underline;
    text-decoration-color: #845ef7;
    text-decoration-thickness: 3px;
    text-underline-offset: 6px;
  }

  h3 {
    text-decoration-color: #339af0;
    text-decoration-thickness: 2px;
    text-underline-offset: 4px;
  }

  /* =========================================
     4. LINKS
     ========================================= */

  a {
    text-decoration-color: #845ef7;
    text-underline-offset: 4px;

    transition:
      color 180ms ease,
      text-decoration-color 180ms ease;
  }

  a:hover {
    color: #d783ff !important;
    text-decoration-color: #ff4d6d;
  }

  /* Rainbow effect for linked headings */
  article h2 a,
  article h3 a,
  [class*="post-card"] h2 a,
  [class*="post-card"] h3 a {
    background: var(--rainbow);
    background-clip: text;
    -webkit-background-clip: text;
    color: transparent !important;
    -webkit-text-fill-color: transparent;
    text-decoration-line: underline;
    text-decoration-color: #bf5af2;
    text-decoration-thickness: 3px;
  }

  /* =========================================
     5. ROUNDED RAINBOW POST CARDS
     ========================================= */

  article,
  [class*="card"],
  [class*="Card"],
  [class*="post-item"],
  [class*="post-card"] {
    border: 1px solid transparent !important;
    border-radius: var(--rainbow-radius) !important;

    background:
      linear-gradient(
        var(--rainbow-card-bg),
        var(--rainbow-card-bg)
      ) padding-box,
      var(--rainbow) border-box !important;

    background-clip: padding-box, border-box;

    transition:
      box-shadow 180ms ease,
      border-color 180ms ease;

    /* Avoid clipping images and content unless needed */
    overflow-wrap: anywhere;
  }

  article:hover,
  [class*="card"]:hover,
  [class*="Card"]:hover,
  [class*="post-item"]:hover,
  [class*="post-card"]:hover {
    box-shadow:
      0 0 12px rgba(132, 94, 247, 0.18),
      0 0 24px rgba(255, 77, 109, 0.08);
  }

  /* Keep nested content from getting its own card background */
  article article,
  [class*="post-card"] article {
    box-shadow: none;
  }

  /* =========================================
     6. NAVIGATION
     ========================================= */

  nav a,
  header a {
    text-underline-offset: 5px;
    text-decoration-thickness: 2px;
  }

  nav a:hover,
  header a:hover {
    text-decoration-line: underline;
    text-decoration-color: #f06595;
  }

  /* =========================================
     7. BUTTONS
     ========================================= */

  button,
  input[type="button"],
  input[type="submit"],
  input[type="reset"],
  [role="button"] {
    border-radius: 10px;

    transition:
      box-shadow 180ms ease,
      transform 180ms ease,
      filter 180ms ease;
  }

  button:hover,
  input[type="button"]:hover,
  input[type="submit"]:hover,
  input[type="reset"]:hover,
  [role="button"]:hover {
    box-shadow: var(--rainbow-shadow);
    filter: saturate(1.2);
  }

  button:active,
  [role="button"]:active {
    transform: scale(0.98);
  }

  /* =========================================
     8. TAGS AND CATEGORY CHIPS
     ========================================= */

  [class*="tag"],
  [class*="badge"],
  [class*="category"],
  [class*="chip"] {
    border-radius: 999px !important;
    border-color: rgba(191, 90, 242, 0.5);
  }

  /* =========================================
     9. SVG ICONS
     ========================================= */

  /* Give SVGs a consistent accent colour */
  svg {
    color: var(--rainbow-purple);
    transition:
      color 180ms ease,
      filter 180ms ease;
  }

  /* Common icon libraries and interface icons */
  svg.lucide,
  svg[class*="icon"],
  button svg,
  a svg,
  nav svg,
  header svg {
    color: var(--rainbow-purple);
  }

  /*
   * Preserve each SVG's shape.
   * Use currentColor so existing fill="none" icons
   * remain outlines rather than becoming solid shapes.
   */
  svg [stroke]:not([stroke="none"]) {
    stroke: currentColor;
  }

  /* Multicolour tint on interactive SVGs */
  button:hover svg,
  a:hover svg,
  nav a:hover svg,
  header a:hover svg,
  svg.lucide:hover,
  svg[class*="icon"]:hover {
    color: var(--rainbow-pink);
    filter: hue-rotate(100deg) saturate(1.8);
  }

  /* SVGs with solid fills */
  svg [fill="currentColor"] {
    fill: currentColor;
  }

  /*
   * Rainbow gradients cannot be defined for arbitrary inline
   * SVGs using CSS alone. Hue rotation is used here instead.
   * Existing SVG gradients and image-based SVGs are preserved.
   */

  /* =========================================
     10. FORM CONTROLS
     ========================================= */

  input:not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):not([type="reset"]),
  textarea,
  select {
    border-radius: 8px;
    accent-color: #845ef7;

    transition:
      border-color 160ms ease,
      box-shadow 160ms ease;
  }

  input:focus,
  textarea:focus,
  select:focus {
    border-color: #845ef7 !important;
    box-shadow: 0 0 0 3px rgba(132, 94, 247, 0.16);
  }

  input[type="checkbox"],
  input[type="radio"],
  progress,
  meter {
    accent-color: #845ef7;
  }

  /* =========================================
     11. SEPARATORS
     ========================================= */

  hr {
    height: 2px;
    border: 0;
    border-radius: 999px;
    background: var(--rainbow);
    opacity: 0.8;
  }

  /* =========================================
     12. BLOCKQUOTES
     ========================================= */

  blockquote {
    border-inline-start: 4px solid #845ef7;
    border-radius: 0 10px 10px 0;
    background: var(--rainbow-soft);
    padding: 0.8em 1em;
  }

  /* =========================================
     13. CODE BLOCKS
     ========================================= */

  pre {
    border-inline-start: 3px solid #339af0;
    border-radius: 10px;
  }

  code {
    text-decoration-color: #845ef7;
    text-decoration-thickness: 1px;
  }

  /* =========================================
     14. TABLES
     ========================================= */

  th {
    border-bottom: 2px solid #845ef7;
  }

  tbody tr:hover {
    background: var(--rainbow-soft);
  }

  /* =========================================
     15. IMAGES AND MEDIA
     ========================================= */

  img,
  video,
  iframe {
    border-radius: 6px;
  }

  /* Do not round tiny icons unnecessarily */
  img[class*="icon"],
  img[class*="avatar"],
  img[class*="emoji"] {
    border-radius: 50%;
  }

  /* =========================================
     16. ACCESSIBILITY
     ========================================= */

  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      scroll-behavior: auto !important;
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
    }
  }
}
